sql.where:
m.source IN ('校宝教材设置', '本地录入')

  AND m.name LIKE CONCAT('%', #{keyword}, '%')


  AND m.category = #{category}


  AND m.status = #{status}


  AND m.qty_total <= 0

m.source IN ('校宝教材设置', '本地录入')

  AND m.name LIKE CONCAT('%', #{keyword}, '%')


  AND m.category = #{category}


  AND m.status = #{status}

m.source = '校宝杂费设置'

  AND m.name LIKE CONCAT('%', #{keyword}, '%')


  AND m.category = #{category}


  AND m.status = #{status}

c.source IN ('校宝库存变动', '本地录入')

  AND (c.material_name LIKE CONCAT('%', #{keyword}, '%')
       OR c.student_name LIKE CONCAT('%', #{keyword}, '%')
       OR c.ext_order_no LIKE CONCAT('%', #{keyword}, '%')
       OR c.handler LIKE CONCAT('%', #{keyword}, '%'))


  AND c.room_name = #{room}


  AND c.biz_type = #{bizType}


  AND c.material_name = #{materialName}


  AND c.change_date >= #{start}


  AND c.change_date <= #{end}
